arguments.cmd:
cat > /app/output/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <meta name="description" content="Global Aid Alliance is a humanitarian nonprofit dedicated to disaster relief, emergency assistance, and community resilience worldwide." />
  <title>Global Aid Alliance — Together We Respond</title>
  <style>
    :root {
      --red-900: #8f1118;
      --red-800: #b31b25;
      --red-700: #c92a34;
      --navy-900: #12304f;
      --gray-900: #1f2937;
      --gray-700: #4b5563;
      --gray-500: #6b7280;
      --gray-200: #e5e7eb;
      --gray-100: #f3f4f6;
      --white: #ffffff;
      --max-width: 1160px;
      --radius: 14px;
      --shadow: 0 14px 35px rgba(18, 48, 79, 0.1);
      --transition: 220ms ease;
    }

    * { box-sizing: border-box; }

    html { scroll-behavior: smooth; }

    body {
      margin: 0;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      color: var(--gray-900);
      background: #fffdfa;
      line-height: 1.55;
    }

    h1, h2, h3, h4 {
      font-family: "Plus Jakarta Sans", Inter, "Segoe UI", sans-serif;
      line-height: 1.2;
      margin: 0;
    }

    p { margin: 0; }

    a {
      color: inherit;
      text-decoration: none;
    }

    img {
      display: block;
      max-width: 100%;
      height: auto;
      border-radius: 12px;
    }

    .container {
      width: min(100% - 2rem, var(--max-width));
      margin-inline: auto;
    }

    .section { padding: 4.5rem 0; }

    .section-title {
      font-size: clamp(1.65rem, 2.8vw, 2.35rem);
      margin-bottom: 1rem;
      color: var(--navy-900);
      letter-spacing: -0.02em;
    }

    .section-subtitle {
      max-width: 62ch;
      color: var(--gray-700);
      margin-bottom: 2rem;
    }

    .btn {
      border: none;
      border-radius: 999px;
      padding: 0.85rem 1.4rem;
      font-weight: 700;
      font-size: 1rem;
      cursor: pointer;
      transition: transform var(--transition), background-color var(--transition), box-shadow var(--transition);
      min-height: 44px;
      min-width: 44px;
    }

    .btn:focus-visible,
    .nav-link:focus-visible,
    .icon-btn:focus-visible,
    .accordion-btn:focus-visible,
    .amount-btn:focus-visible,
    .social-link:focus-visible {
      outline: 3px solid #f4b6bc;
      outline-offset: 3px;
    }

    .btn-primary {
      background: var(--red-800);
      color: var(--white);
      box-shadow: 0 10px 24px rgba(179, 27, 37, 0.28);
    }

    .btn-primary:hover { background: var(--red-700); transform: translateY(-1px); }

    .btn-secondary {
      background: transparent;
      border: 1px solid var(--gray-200);
      color: var(--navy-900);
    }

    .btn-secondary:hover { background: var(--gray-100); }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 50;
      background: rgba(255, 255, 255, 0.97);
      backdrop-filter: blur(8px);
      border-bottom: 1px solid var(--gray-200);
    }

    .header-inner {
      height: 78px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      min-width: 0;
    }

    .brand-mark {
      width: 42px;
      height: 42px;
      border-radius: 50%;
      background: linear-gradient(150deg, var(--red-900), var(--red-700));
      color: white;
      display: grid;
      place-items: center;
      font-weight: 800;
      font-size: 0.95rem;
    }

    .brand-text { min-width: 0; }

    .brand-title {
      font-size: 1rem;
      color: var(--navy-900);
      white-space: nowrap;
    }

    .brand-sub {
      font-size: 0.72rem;
      color: var(--gray-500);
      letter-spacing: 0.02em;
      text-transform: uppercase;
    }

    .desktop-nav {
      display: flex;
      align-items: center;
      gap: 1.25rem;
    }

    .nav-link {
      font-weight: 600;
      color: var(--gray-700);
      padding: 0.55rem 0.3rem;
      transition: color var(--transition);
      min-height: 44px;
      display: inline-flex;
      align-items: center;
    }

    .nav-link:hover { color: var(--red-800); }

    .mobile-toggle {
      display: none;
      background: transparent;
      border: none;
      width: 44px;
      height: 44px;
      border-radius: 10px;
      cursor: pointer;
    }

    .mobile-toggle span {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--gray-900);
      margin: 5px auto;
      transition: var(--transition);
    }

    .mobile-drawer {
      display: none;
      border-top: 1px solid var(--gray-200);
      max-height: 0;
      overflow: hidden;
      opacity: 0;
      transform: translateY(-8px);
      transition: max-height 300ms ease, opacity 260ms ease, transform 260ms ease;
      background: var(--white);
    }

    .mobile-drawer.open {
      max-height: 420px;
      opacity: 1;
      transform: translateY(0);
    }

    .mobile-nav {
      display: grid;
      gap: 0.25rem;
      padding: 0.9rem 0 1rem;
    }

    .mobile-nav .nav-link {
      padding: 0.7rem 0.2rem;
      width: fit-content;
    }

    .hero {
      background: linear-gradient(135deg, #fdf4f5 0%, #fff 36%, #f5f8fd 100%);
      border-bottom: 1px solid var(--gray-200);
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 2.2rem;
      align-items: center;
      padding: 4.2rem 0;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      background: #fcecee;
      color: var(--red-900);
      font-weight: 700;
      border-radius: 999px;
      padding: 0.3rem 0.7rem;
      margin-bottom: 1rem;
      font-size: 0.82rem;
    }

    .hero h1 {
      font-size: clamp(2rem, 5.4vw, 3.5rem);
      color: var(--navy-900);
      letter-spacing: -0.02em;
      margin-bottom: 1rem;
    }

    .hero p {
      color: var(--gray-700);
      max-width: 60ch;
      margin-bottom: 1.5rem;
    }

    .hero-actions {
      display: flex;
      gap: 0.8rem;
      flex-wrap: wrap;
    }

    .hero-image-wrap {
      position: relative;
      isolation: isolate;
    }

    .hero-image-wrap::before {
      content: "";
      position: absolute;
      inset: -15px -15px auto auto;
      width: 140px;
      height: 140px;
      border-radius: 50%;
      background: #e9f2ff;
      z-index: -1;
    }

    .hero-card {
      margin-top: 0.9rem;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: 1rem;
      display: flex;
      gap: 0.9rem;
      align-items: center;
    }

    .hero-card strong {
      display: block;
      color: var(--navy-900);
      margin-bottom: 0.1rem;
    }

    .hero-card p { margin: 0; font-size: 0.9rem; color: var(--gray-700); }

    .mission-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1.5rem;
    }

    .mission-card {
      border: 1px solid var(--gray-200);
      background: white;
      border-radius: var(--radius);
      padding: 1.3rem;
    }

    .mission-card h3 {
      margin-bottom: 0.6rem;
      color: var(--navy-900);
      font-size: 1.1rem;
    }

    .mission-card p { color: var(--gray-700); }

    .stats-wrap {
      background: var(--navy-900);
      color: white;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1rem;
    }

    .stat-card {
      background: rgba(255, 255, 255, 0.06);
      border: 1px solid rgba(255, 255, 255, 0.14);
      border-radius: 12px;
      padding: 1.3rem;
      text-align: center;
    }

    .stat-num {
      font-size: clamp(1.7rem, 4vw, 2.7rem);
      font-weight: 800;
      margin-bottom: 0.35rem;
      letter-spacing: -0.02em;
    }

    .stat-label {
      color: #d2deee;
      font-size: 0.95rem;
      font-weight: 500;
    }

    .programs-layout {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1.5rem;
      align-items: start;
    }

    .accordion {
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      overflow: hidden;
      background: white;
    }

    .accordion-item + .accordion-item { border-top: 1px solid var(--gray-200); }

    .accordion-btn {
      width: 100%;
      border: none;
      background: white;
      cursor: pointer;
      text-align: left;
      padding: 1rem 1rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      font-size: 1rem;
      font-weight: 700;
      color: var(--navy-900);
      min-height: 56px;
    }

    .accordion-icon {
      width: 24px;
      height: 24px;
      border-radius: 50%;
      background: #f6f8fc;
      border: 1px solid var(--gray-200);
      display: grid;
      place-items: center;
      flex-shrink: 0;
      color: var(--gray-700);
      transition: transform var(--transition);
    }

    .accordion-item.open .accordion-icon { transform: rotate(180deg); }

    .accordion-panel {
      display: grid;
      grid-template-rows: 0fr;
      transition: grid-template-rows 280ms ease;
    }

    .accordion-item.open .accordion-panel { grid-template-rows: 1fr; }

    .accordion-content {
      overflow: hidden;
      padding: 0 1rem;
    }

    .accordion-content-inner {
      padding-bottom: 1rem;
      color: var(--gray-700);
      border-top: 1px solid #eef1f5;
      padding-top: 0.9rem;
    }

    .involved-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
    }

    .involved-card {
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 1.2rem;
      background: white;
    }

    .involved-card h3 {
      color: var(--navy-900);
      margin-bottom: 0.5rem;
      font-size: 1.08rem;
    }

    .involved-card p {
      color: var(--gray-700);
      margin-bottom: 1rem;
      min-height: 72px;
    }

    .news-shell {
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 1rem;
      background: white;
    }

    .news-toolbar {
      display: flex;
      justify-content: flex-end;
      gap: 0.55rem;
      margin-bottom: 0.7rem;
    }

    .icon-btn {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 1px solid var(--gray-200);
      background: white;
      cursor: pointer;
      font-size: 1.05rem;
      color: var(--navy-900);
    }

    .icon-btn:hover { background: #f7f9fc; }

    .news-window { overflow: hidden; }

    .news-track {
      display: flex;
      transition: transform 320ms ease;
      will-change: transform;
    }

    .news-card {
      min-width: calc(100% / 3);
      padding: 0.55rem;
    }

    .news-inner {
      border: 1px solid var(--gray-200);
      border-radius: 12px;
      overflow: hidden;
      height: 100%;
      background: #fff;
    }

    .news-content { padding: 0.9rem; }

    .news-content h3 {
      font-size: 1.02rem;
      color: var(--navy-900);
      margin-bottom: 0.4rem;
    }

    .news-meta {
      font-size: 0.82rem;
      color: var(--gray-500);
      margin-bottom: 0.5rem;
      display: block;
    }

    .donate-band {
      background: linear-gradient(125deg, #fff, #fef4f5 45%, #f4f8ff 100%);
      border-top: 1px solid var(--gray-200);
      border-bottom: 1px solid var(--gray-200);
    }

    .donate-box {
      display: grid;
      grid-template-columns: 1.2fr auto;
      gap: 1rem;
      align-items: center;
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 1.4rem;
      background: white;
      box-shadow: var(--shadow);
    }

    .donate-box h2 { color: var(--navy-900); margin-bottom: 0.4rem; }

    .donate-box p { color: var(--gray-700); }

    .site-footer {
      background: #121a26;
      color: #e7ecf3;
      padding-top: 3rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1.5rem;
      padding-bottom: 2rem;
    }

    .footer-grid h4 {
      font-size: 1rem;
      margin-bottom: 0.8rem;
      color: white;
    }

    .footer-link {
      display: block;
      color: #c2cedf;
      margin-bottom: 0.5rem;
      min-height: 32px;
    }

    .footer-link:hover { color: white; }

    .footer-bottom {
      border-top: 1px solid rgba(255, 255, 255, 0.15);
      padding: 1rem 0 1.5rem;
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
      align-items: center;
    }

    .socials {
      display: flex;
      gap: 0.5rem;
      flex-wrap: wrap;
    }

    .social-link {
      border: 1px solid rgba(255, 255, 255, 0.2);
      border-radius: 999px;
      padding: 0.4rem 0.75rem;
      min-height: 36px;
      display: inline-flex;
      align-items: center;
      color: #dae4f2;
      font-size: 0.88rem;
    }

    .social-link:hover { background: rgba(255, 255, 255, 0.08); color: white; }

    .modal-backdrop {
      position: fixed;
      inset: 0;
      background: rgba(5, 15, 28, 0.62);
      display: none;
      align-items: center;
      justify-content: center;
      padding: 1rem;
      z-index: 100;
    }

    .modal-backdrop.open { display: flex; }

    .modal {
      width: min(560px, 100%);
      background: white;
      border-radius: 16px;
      box-shadow: 0 35px 85px rgba(0, 0, 0, 0.25);
      border: 1px solid var(--gray-200);
      overflow: hidden;
    }

    .modal-head {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 1rem;
      border-bottom: 1px solid var(--gray-200);
    }

    .modal-head h3 { color: var(--navy-900); }

    .modal-close {
      width: 40px;
      height: 40px;
      border: 1px solid var(--gray-200);
      background: #fff;
      border-radius: 8px;
      cursor: pointer;
      font-size: 1.05rem;
      color: var(--gray-700);
    }

    .modal-body { padding: 1rem; }

    .amount-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 0.6rem;
      margin: 0.9rem 0 1rem;
    }

    .amount-btn {
      border: 1px solid var(--gray-200);
      background: white;
      border-radius: 10px;
      min-height: 52px;
      cursor: pointer;
      font-weight: 700;
      color: var(--navy-900);
    }

    .amount-btn.active {
      background: #fceced;
      border-color: #f4b6bc;
      color: var(--red-900);
    }

    .custom-amount,
    .donor-name,
    .donor-email {
      width: 100%;
      border: 1px solid var(--gray-200);
      border-radius: 10px;
      padding: 0.7rem 0.8rem;
      font-size: 1rem;
      margin-top: 0.5rem;
      margin-bottom: 0.8rem;
      min-height: 44px;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      border: 0;
    }

    @media (max-width: 1024px) {
      .news-card { min-width: calc(100% / 2); }
      .hero-grid,
      .programs-layout,
      .mission-grid,
      .donate-box { grid-template-columns: 1fr; }
      .involved-grid { grid-template-columns: 1fr 1fr; }
      .stats-grid { grid-template-columns: 1fr 1fr; }
      .footer-grid { grid-template-columns: 1fr 1fr; }
    }

    @media (max-width: 760px) {
      .desktop-nav,
      .header-actions { display: none; }
      .mobile-toggle,
      .mobile-drawer { display: block; }
      .section { padding: 3.4rem 0; }
      .hero-grid { padding: 2.8rem 0 3rem; }
      .involved-grid,
      .stats-grid,
      .footer-grid,
      .amount-grid,
      .news-card { grid-template-columns: 1fr; }
      .news-card { min-width: 100%; }
      .footer-bottom { flex-direction: column; align-items: flex-start; }
      .brand-title { white-space: normal; }
      .donate-box { padding: 1rem; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 1ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 1ms !important;
        scroll-behavior: auto !important;
      }
    }
  </style>
</head>
<body>
  <header class="site-header">
    <div class="container header-inner">
      <a href="#home" class="brand" aria-label="Global Aid Alliance home">
        <div class="brand-mark" aria-hidden="true">GAA</div>
        <div class="brand-text">
          <strong class="brand-title">Global Aid Alliance</strong>
          <div class="brand-sub">Together We Respond</div>
        </div>
      </a>

      <nav class="desktop-nav" aria-label="Main navigation">
        <a class="nav-link" href="#programs">Disaster Relief</a>
        <a class="nav-link" href="#programs">Programs</a>
        <a class="nav-link" href="#volunteer">Volunteer</a>
        <a class="nav-link" href="#mission">About Us</a>
        <a class="nav-link" href="#news">News</a>
      </nav>

      <div class="header-actions">
        <button class="btn btn-primary js-open-donate" type="button">Donate</button>
      </div>

      <button class="mobile-toggle" type="button" aria-expanded="false" aria-controls="mobileDrawer" aria-label="Open mobile menu" id="mobileToggle">
        <span></span><span></span><span></span>
      </button>
    </div>

    <div class="mobile-drawer" id="mobileDrawer">
      <div class="container">
        <nav class="mobile-nav" aria-label="Mobile navigation">
          <a class="nav-link" href="#programs">Disaster Relief</a>
          <a class="nav-link" href="#programs">Programs</a>
          <a class="nav-link" href="#volunteer">Volunteer</a>
          <a class="nav-link" href="#mission">About Us</a>
          <a class="nav-link" href="#news">News</a>
          <button class="btn btn-primary js-open-donate" type="button">Donate</button>
        </nav>
      </div>
    </div>
  </header>

  <main id="home">
    <section class="hero">
      <div class="container hero-grid">
        <div>
          <div class="eyebrow">Emergency Response · Community Resilience</div>
          <h1>Together We Respond. Together We Rebuild.</h1>
          <p>Global Aid Alliance delivers rapid disaster relief, lifesaving medical support, and long-term recovery programs in communities facing crisis. From hurricanes and wildfires to floods and conflict zones, we help people recover with dignity.</p>
          <div class="hero-actions">
            <button class="btn btn-primary js-open-donate" type="button">Donate Now</button>
            <a class="btn btn-secondary" href="#volunteer">Volunteer Today</a>
          </div>
          <article class="hero-card" aria-label="Current emergency update">
            <div aria-hidden="true">🧭</div>
            <div>
              <strong>Current Response Priority</strong>
              <p>Emergency relief teams are active across storm-affected coastal communities with shelter, water, and medical aid.</p>
            </div>
          </article>
        </div>

        <div class="hero-image-wrap">
          <img src="https://images.unsplash.com/photo-1593113598332-cd288d649433?auto=format&fit=crop&w=1200&q=80" alt="Relief workers distributing emergency supplies to diverse families in a disaster-affected community" loading="eager" width="1200" height="800" />
        </div>
      </div>
    </section>

    <section class="section" id="mission">
      <div class="container">
        <h2 class="section-title">Our Mission</h2>
        <p class="section-subtitle">We exist to prevent and alleviate human suffering during and after disasters by mobilizing volunteers, community partners, and local leadership in more than 190 countries.</p>
        <div class="mission-grid">
          <article class="mission-card">
            <h3>Rapid Emergency Assistance</h3>
            <p>When disaster strikes, we provide shelter, food, clean water, blood support, and emergency health services within hours.</p>
          </article>
          <article class="mission-card">
            <h3>Resilience for the Long Term</h3>
            <p>Beyond immediate relief, we invest in preparedness training, infrastructure recovery, and community health to reduce future risk.</p>
          </article>
        </div>
      </div>
    </section>

    <section class="section stats-wrap" aria-labelledby="impactHeading">
      <div class="container">
        <h2 id="impactHeading" class="section-title" style="color: white;">Impact at a Glance</h2>
        <p class="section-subtitle" style="color:#d6e0ef;">Your support powers lifesaving aid and long-term recovery in vulnerable communities worldwide.</p>
        <div class="stats-grid">
          <article class="stat-card">
            <div class="stat-num" data-target="12" data-suffix="M">0</div>
            <div class="stat-label">People Helped</div>
          </article>
          <article class="stat-card">
            <div class="stat-num" data-target="50000" data-format="comma">0</div>
            <div class="stat-label">Active Volunteers</div>
          </article>
          <article class="stat-card">
            <div class="stat-num" data-target="190">0</div>
            <div class="stat-label">Countries Served</div>
          </article>
          <article class="stat-card">
            <div class="stat-num" data-target="850" data-prefix="$" data-suffix="M">0</div>
            <div class="stat-label">Raised for Humanitarian Work</div>
          </article>
        </div>
      </div>
    </section>

    <section class="section" id="programs">
      <div class="container programs-layout">
        <div>
          <h2 class="section-title">Programs and Services</h2>
          <p class="section-subtitle">Our integrated programs support urgent response and sustainable recovery in communities facing climate, conflict, and health emergencies.</p>
          <img src="https://images.unsplash.com/photo-1618477462146-050d2767eac4?auto=format&fit=crop&w=1200&q=80" alt="Volunteers and aid workers coordinating emergency preparedness and community relief operations" loading="lazy" width="1200" height="800" />
        </div>

        <div class="accordion" id="programAccordion">
          <article class="accordion-item open">
