    .mission-card p { color: var(--gray-700); }

    .stats-wrap {
      background: var(--navy-900);
      color: white;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1rem;
    }

    .stat-card {
      background: rgba(255, 255, 255, 0.06);
      border: 1px solid rgba(255, 255, 255, 0.14);
      border-radius: 12px;
      padding: 1.3rem;
      text-align: center;
    }

    .stat-num {
      font-size: clamp(1.7rem, 4vw, 2.7rem);
      font-weight: 800;
      margin-bottom: 0.35rem;
      letter-spacing: -0.02em;
    }

    .stat-label {
      color: #d2deee;
      font-size: 0.95rem;
      font-weight: 500;
    }

    .programs-layout {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1.5rem;
      align-items: start;
    }

    .accordion {
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      overflow: hidden;
      background: white;
    }

    .accordion-item + .accordion-item { border-top: 1px solid var(--gray-200); }

    .accordion-btn {
      width: 100%;
      border: none;
      background: white;
      cursor: pointer;
      text-align: left;
      padding: 1rem 1rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      font-size: 1rem;
      font-weight: 700;
      color: var(--navy-900);
      min-height: 56px;
    }

    .accordion-icon {
      width: 24px;
      height: 24px;
      border-radius: 50%;
      background: #f6f8fc;
      border: 1px solid var(--gray-200);
      display: grid;
      place-items: center;
      flex-shrink: 0;
      color: var(--gray-700);
      transition: transform var(--transition);
    }

    .accordion-item.open .accordion-icon { transform: rotate(180deg); }

    .accordion-panel {
      display: grid;
      grid-template-rows: 0fr;
      transition: grid-template-rows 280ms ease;
    }

    .accordion-item.open .accordion-panel { grid-template-rows: 1fr; }

    .accordion-content {
      overflow: hidden;
      padding: 0 1rem;
    }

    .accordion-content-inner {
      padding-bottom: 1rem;
      color: var(--gray-700);
      border-top: 1px solid #eef1f5;
      padding-top: 0.9rem;
    }

    .involved-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
    }

    .involved-card {
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 1.2rem;
      background: white;
    }

    .involved-card h3 {
      color: var(--navy-900);
      margin-bottom: 0.5rem;
      font-size: 1.08rem;
    }

    .involved-card p {
      color: var(--gray-700);
      margin-bottom: 1rem;
      min-height: 72px;
    }

    .news-shell {
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 1rem;
      background: white;
    }

    .news-toolbar {
      display: flex;
      justify-content: flex-end;
      gap: 0.55rem;
      margin-bottom: 0.7rem;
    }

    .icon-btn {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 1px solid var(--gray-200);
      background: white;
      cursor: pointer;
      font-size: 1.05rem;
      color: var(--navy-900);
    }

    .icon-btn:hover { background: #f7f9fc; }

    .news-window { overflow: hidden; }

    .news-track {
      display: flex;
      transition: transform 320ms ease;
      will-change: transform;
    }

    .news-card {
      min-width: calc(100% / 3);
      padding: 0.55rem;
    }

    .news-inner {
      border: 1px solid var(--gray-200);
      border-radius: 12px;
      overflow: hidden;
      height: 100%;
      background: #fff;
    }

    .news-content { padding: 0.9rem; }

    .news-content h3 {
      font-size: 1.02rem;
      color: var(--navy-900);
      margin-bottom: 0.4rem;
    }

    .news-meta {
      font-size: 0.82rem;
      color: var(--gray-500);
      margin-bottom: 0.5rem;
      display: block;
    }

    .donate-band {
      background: linear-gradient(125deg, #fff, #fef4f5 45%, #f4f8ff 100%);
      border-top: 1px solid var(--gray-200);
      border-bottom: 1px solid var(--gray-200);
    }

    .donate-box {
      display: grid;
      grid-template-columns: 1.2fr auto;
      gap: 1rem;
      align-items: center;
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 1.4rem;
      background: white;
      box-shadow: var(--shadow);
    }

    .donate-box h2 { color: var(--navy-900); margin-bottom: 0.4rem; }

    .donate-box p { color: var(--gray-700); }

    .site-footer {
      background: #121a26;
      color: #e7ecf3;
      padding-top: 3rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1.5rem;
      padding-bottom: 2rem;
    }

    .footer-grid h4 {
      font-size: 1rem;
      margin-bottom: 0.8rem;
      color: white;
    }

    .footer-link {
      display: block;
      color: #c2cedf;
      margin-bottom: 0.5rem;
      min-height: 32px;
    }

    .footer-link:hover { color: white; }

    .footer-bottom {
      border-top: 1px solid rgba(255, 255, 255, 0.15);
      padding: 1rem 0 1.5rem;
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
      align-items: center;
    }

    .socials {
      display: flex;
      gap: 0.5rem;
      flex-wrap: wrap;
    }

    .social-link {
      border: 1px solid rgba(255, 255, 255, 0.2);
      border-radius: 999px;
      padding: 0.4rem 0.75rem;
      min-height: 36px;
      display: inline-flex;
      align-items: center;
      color: #dae4f2;
      font-size: 0.88rem;
    }

    .social-link:hover { background: rgba(255, 255, 255, 0.08); color: white; }

    .modal-backdrop {
      position: fixed;
      inset: 0;
      background: rgba(5, 15, 28, 0.62);
      display: none;
      align-items: center;
      justify-content: center;
      padding: 1rem;
      z-index: 100;
    }

    .modal-backdrop.open { display: flex; }

    .modal {
      width: min(560px, 100%);
      background: white;
      border-radius: 16px;
      box-shadow: 0 35px 85px rgba(0, 0, 0, 0.25);
      border: 1px solid var(--gray-200);
      overflow: hidden;
    }

    .modal-head {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 1rem;
      border-bottom: 1px solid var(--gray-200);
    }

    .modal-head h3 { color: var(--navy-900); }

    .modal-close {
      width: 40px;
      height: 40px;
      border: 1px solid var(--gray-200);
      background: #fff;
      border-radius: 8px;
      cursor: pointer;
      font-size: 1.05rem;
      color: var(--gray-700);
    }

    .modal-body { padding: 1rem; }

    .amount-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 0.6rem;
      margin: 0.9rem 0 1rem;
    }

    .amount-btn {
      border: 1px solid var(--gray-200);
      background: white;
      border-radius: 10px;
      min-height: 52px;
      cursor: pointer;
      font-weight: 700;
      color: var(--navy-900);
    }

    .amount-btn.active {
      background: #fceced;
      border-color: #f4b6bc;
      color: var(--red-900);
    }

    .custom-amount,
    .donor-name,
    .donor-email {
      width: 100%;
      border: 1px solid var(--gray-200);
      border-radius: 10px;
      padding: 0.7rem 0.8rem;
      font-size: 1rem;
      margin-top: 0.5rem;
      margin-bottom: 0.8rem;
      min-height: 44px;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      border: 0;
    }

    @media (max-width: 1024px) {
      .news-card { min-width: calc(100% / 2); }
      .hero-grid,
      .programs-layout,
      .mission-grid,
      .donate-box { grid-template-columns: 1fr; }
      .involved-grid { grid-template-columns: 1fr 1fr; }
      .stats-grid { grid-template-columns: 1fr 1fr; }
      .footer-grid { grid-template-columns: 1fr 1fr; }
    }

    @media (max-width: 760px) {
      .desktop-nav,
      .header-actions { display: none; }
      .mobile-toggle,
      .mobile-drawer { display: block; }
      .section { padding: 3.4rem 0; }
      .hero-grid { padding: 2.8rem 0 3rem; }
      .involved-grid,
      .stats-grid,
      .footer-grid,
      .amount-grid,
      .news-card { grid-template-columns: 1fr; }
      .news-card { min-width: 100%; }
      .footer-bottom { flex-direction: column; align-items: flex-start; }
      .brand-title { white-space: normal; }
      .donate-box { padding: 1rem; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 1ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 1ms !important;
        scroll-behavior: auto !important;
      }
    }
  </style>
</head>
