        </div>

        <div class="hero-image-wrap">
          <img src="https://images.unsplash.com/photo-1593113598332-cd288d649433?auto=format&fit=crop&w=1200&q=80" alt="Relief workers distributing emergency supplies to diverse families in a disaster-affected community" loading="eager" width="1200" height="800" />
        </div>
      </div>
