        <a class="social-link" href="#" aria-label="Visit Global Aid Alliance on Facebook">Facebook</a>
        <a class="social-link" href="#" aria-label="Visit Global Aid Alliance on X">X (Twitter)</a>
        <a class="social-link" href="#" aria-label="Visit Global Aid Alliance on Instagram">Instagram</a>
        <a class="social-link" href="#" aria-label="Visit Global Aid Alliance on LinkedIn">LinkedIn</a>
        <a class="social-link" href="#" aria-label="Visit Global Aid Alliance on YouTube">YouTube</a>
      </div>
    </div>
  </footer>

  <div class="modal-backdrop" id="donateModal" role="dialog" aria-modal="true" aria-labelledby="donateTitle" aria-hidden="true">
    <div class="modal">
      <div class="modal-head">
        <h3 id="donateTitle">Make a Lifesaving Donation</h3>
        <button type="button" class="modal-close" id="closeDonateModal" aria-label="Close donation modal">✕</button>
      </div>
      <div class="modal-body">
        <p>Your contribution supports communities in crisis. Choose an amount below:</p>

        <div class="amount-grid" role="group" aria-label="Donation amounts">
          <button class="amount-btn" type="button" data-amount="25">$25</button>
          <button class="amount-btn" type="button" data-amount="50">$50</button>
          <button class="amount-btn active" type="button" data-amount="100">$100</button>
          <button class="amount-btn" type="button" data-amount="250">$250</button>
          <button class="amount-btn" type="button" data-amount="500">$500</button>
          <button class="amount-btn" type="button" data-amount="custom">Custom</button>
        </div>

        <label for="customAmount">Custom Amount (USD)</label>
        <input class="custom-amount" id="customAmount" type="number" min="1" step="1" placeholder="Enter custom amount" aria-label="Custom amount in dollars" />

        <label for="donorName">Full Name</label>
        <input class="donor-name" id="donorName" type="text" placeholder="Your full name" />

        <label for="donorEmail">Email Address</label>
        <input class="donor-email" id="donorEmail" type="email" placeholder="you@example.com" />

        <button type="button" class="btn btn-primary" style="width: 100%;" id="submitDonation">Donate Now</button>
      </div>
    </div>
  </div>

  <script>
    const body = document.body;

    const mobileToggle = document.getElementById('mobileToggle');
    const mobileDrawer = document.getElementById('mobileDrawer');

    mobileToggle?.addEventListener('click', () => {
      const isOpen = mobileDrawer.classList.toggle('open');
      mobileToggle.setAttribute('aria-expanded', String(isOpen));
    });

    mobileDrawer?.querySelectorAll('a, button').forEach((link) => {
      link.addEventListener('click', () => {
        mobileDrawer.classList.remove('open');
        mobileToggle.setAttribute('aria-expanded', 'false');
      });
    });

    const modal = document.getElementById('donateModal');
    const closeModalBtn = document.getElementById('closeDonateModal');
    const openModalButtons = document.querySelectorAll('.js-open-donate');
    let lastFocusedElement = null;

    const openDonateModal = () => {
      lastFocusedElement = document.activeElement;
      modal.classList.add('open');
      modal.setAttribute('aria-hidden', 'false');
      body.style.overflow = 'hidden';
      document.getElementById('submitDonation').focus();
    };

    const closeDonateModal = () => {
      modal.classList.remove('open');
      modal.setAttribute('aria-hidden', 'true');
      body.style.overflow = '';
      if (lastFocusedElement) lastFocusedElement.focus();
    };

    openModalButtons.forEach((button) => button.addEventListener('click', openDonateModal));
    closeModalBtn.addEventListener('click', closeDonateModal);

    modal.addEventListener('click', (event) => {
      if (event.target === modal) closeDonateModal();
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && modal.classList.contains('open')) {
        closeDonateModal();
      }
    });

    const amountButtons = document.querySelectorAll('.amount-btn');
    const customAmountInput = document.getElementById('customAmount');

    amountButtons.forEach((button) => {
      button.addEventListener('click', () => {
        amountButtons.forEach((item) => item.classList.remove('active'));
        button.classList.add('active');
        if (button.dataset.amount === 'custom') {
          customAmountInput.focus();
        }
      });
    });

    const submitDonation = document.getElementById('submitDonation');
    submitDonation.addEventListener('click', () => {
      const active = document.querySelector('.amount-btn.active');
      const selected = active?.dataset.amount;
      const amount = selected === 'custom' ? (customAmountInput.value || 'custom amount') : `$${selected}`;
      submitDonation.textContent = `Thank you for donating ${amount}!`;
      submitDonation.disabled = true;
      setTimeout(() => {
        submitDonation.textContent = 'Donate Now';
        submitDonation.disabled = false;
        closeDonateModal();
      }, 1400);
    });

    const accordionItems = document.querySelectorAll('.accordion-item');

    accordionItems.forEach((item) => {
      const button = item.querySelector('.accordion-btn');
      button.addEventListener('click', () => {
        const isOpen = item.classList.contains('open');
        accordionItems.forEach((entry) => {
          entry.classList.remove('open');
          entry.querySelector('.accordion-btn').setAttribute('aria-expanded', 'false');
        });
        if (!isOpen) {
          item.classList.add('open');
          button.setAttribute('aria-expanded', 'true');
        }
      });
    });

    const newsTrack = document.getElementById('newsTrack');
    const nextNews = document.getElementById('nextNews');
    const prevNews = document.getElementById('prevNews');
    const cards = Array.from(document.querySelectorAll('.news-card'));
    let currentSlide = 0;

    const getVisibleCards = () => {
      if (window.innerWidth <= 760) return 1;
      if (window.innerWidth <= 1024) return 2;
      return 3;
    };

    const updateNewsCarousel = () => {
      const visible = getVisibleCards();
      const maxIndex = Math.max(0, cards.length - visible);
      if (currentSlide > maxIndex) currentSlide = maxIndex;
      const cardWidth = cards[0].getBoundingClientRect().width;
      newsTrack.style.transform = `translateX(-${currentSlide * cardWidth}px)`;
      prevNews.disabled = currentSlide === 0;
      nextNews.disabled = currentSlide >= maxIndex;
    };

    nextNews.addEventListener('click', () => {
      const max = Math.max(0, cards.length - getVisibleCards());
      if (currentSlide < max) {
        currentSlide += 1;
        updateNewsCarousel();
      }
    });

    prevNews.addEventListener('click', () => {
      if (currentSlide > 0) {
        currentSlide -= 1;
        updateNewsCarousel();
      }
    });

    window.addEventListener('resize', updateNewsCarousel);

    const statNodes = document.querySelectorAll('.stat-num');

    const animateCount = (node) => {
      const target = Number(node.dataset.target || 0);
      const prefix = node.dataset.prefix || '';
      const suffix = node.dataset.suffix || '';
      const comma = node.dataset.format === 'comma';
      const duration = 1400;
      const start = performance.now();

      const render = (now) => {
        const progress = Math.min((now - start) / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        const value = Math.floor(target * eased);
        const display = comma ? value.toLocaleString('en-US') : value;
        node.textContent = `${prefix}${display}${suffix}`;
        if (progress < 1) requestAnimationFrame(render);
      };

      requestAnimationFrame(render);
    };

    const statsObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          animateCount(entry.target);
          statsObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.45 });

    statNodes.forEach((node) => statsObserver.observe(node));

    updateNewsCarousel();
  </script>
</body>
</html>
